  }
})

test("applies warning and hard boundaries without truncation", () => {
  assert.equal(assessSourceSize("a".repeat(WARNING_SOURCE_BYTES)).level, "safe");
  assert.equal(assessSourceSize("a".repeat(WARNING_SOURCE_BYTES + 1)).level, "warning");
  assert.equal(assessSourceSize("a".repeat(MAXIMUM_SOURCE_BYTES)).level, "warning");
  const blocked = assessSourceSize("a".repeat(MAXIMUM_SOURCE_BYTES + 1));
  assert.deepEqual(blocked, { bytes: MAXIMUM_SOURCE_BYTES + 1, level: "blocked" });
})

test("rejects missing and empty selections", () => {
  assert.deepEqual(collectSelectionText("abc", [], "\n"), { ok: false, reason: "empty-selection" });
  assert.deepEqual(collectSelectionText("abc", [{ anchor: 1, active: 1 }], "\n"), {
    ok: false,
    reason: "empty-selection",
  });
})

test("sorts reversed selections and joins them with the document EOL", () => {
  const source = "zero one two three";
  const result = collectSelectionText(source, [
    { anchor: 18, active: 13 },
    { anchor: 8, active: 5 },
  ], "\r\n");
  assert.deepEqual(result, {
    ok: true,
    ranges: [{ start: 5, end: 8 }, { start: 13, end: 18 }],
    text: "one\r\nthree",
  });
})

test("unions overlaps without duplicating source text", () => {
  const result = collectSelectionText("abcdefgh", [
    { anchor: 1, active: 5 },
    { anchor: 3, active: 7 },
    { anchor: 2, active: 4 },
  ], "\n");
  assert.deepEqual(result, {
    ok: true,
    ranges: [{ start: 1, end: 7 }],
    text: "bcdefg",
  });
})

test("keeps adjacent selections distinct", () => {
  const result = collectSelectionText("abcd", [
    { anchor: 0, active: 2 },
    { anchor: 2, active: 4 },
  ], "\n");
  assert.equal(result.ok, true);
  if (result.ok) assert.equal(result.text, "ab\ncd");
})

test("preserves Unicode, emoji, nulls, and partial lines exactly", () => {
  const source = "prefix\n😀\0中 suffix\nend";
  const start = source.indexOf("😀");
  const end = source.indexOf(" suffix") + 4;
  const result = collectSelectionText(source, [{ anchor: start, active: end }], "\n");
  assert.equal(result.ok, true);
  if (result.ok) assert.equal(result.text, source.slice(start, end));
})

test("rejects offsets outside the document", () => {
  assert.deepEqual(collectSelectionText("abc", [{ anchor: -1, active: 2 }], "\n"), {
    ok: false,
    reason: "invalid-selection",
  });
  assert.deepEqual(collectSelectionText("abc", [{ anchor: 0, active: 4 }], "\n"), {
    ok: false,
    reason: "invalid-selection",
  });
})

test("creates immutable snapshots and returns exact content", () => {
  let now = 10;
  const store = new SnapshotStore({ now: () => now, createId: idFactory() });
  const created = store.createMany([input("secret\0😀")]);
  assert.equal(created.ok, true);
  if (!created.ok) return;
  const snapshot = created.snapshots[0];
  assert.equal(Object.isFrozen(snapshot), true);
  assert.equal(store.get(snapshot.id)?.text, "secret\0😀");
  assert.equal(snapshot.createdAt, 10);
  now += 1;
})

test("evicts the oldest unreferenced snapshot deterministically", () => {
  let now = 0;
  const store = new SnapshotStore({ maximum: 2, ttlMs: 1_000, now: () => now, createId: idFactory() });
  const first = store.createMany([input("first")]);
  assert.equal(first.ok, true);
  now = 1;
  const second = store.createMany([input("second")]);
  assert.equal(second.ok, true);
  now = 2;
  const third = store.createMany([input("third")]);
  assert.equal(third.ok, true);
  if (!first.ok || !second.ok || !third.ok) return;
  assert.equal(store.get(first.snapshots[0].id), undefined);
  assert.equal(store.get(second.snapshots[0].id)?.text, "second");
  assert.equal(store.get(third.snapshots[0].id)?.text, "third");
})

test("retained snapshots block unsafe eviction", () => {
  const store = new SnapshotStore({ maximum: 2, createId: idFactory() });
  const pinned = store.createMany([input("left"), input("right")], [true, true]);
  assert.equal(pinned.ok, true);
  assert.deepEqual(store.createMany([input("extra")]), { ok: false, reason: "capacity" });
})

test("expires only after a snapshot becomes unreferenced", () => {
  let now = 0;
  const store = new SnapshotStore({ ttlMs: 100, now: () => now, createId: idFactory() });
  const created = store.createMany([input("open")], [true]);
  assert.equal(created.ok, true);
  if (!created.ok) return;
  const id = created.snapshots[0].id;
  now = 500;
  assert.equal(store.prune(), 0);
  store.release(id);
  assert.equal(store.nextExpiryAt(), 600);
  now = 599;
  assert.equal(store.prune(), 0);
  now = 600;
  assert.equal(store.prune(), 1);
  assert.equal(store.size, 0);
})

test("replaces the retained left snapshot without mutating its text", () => {
  const store = new SnapshotStore({ maximum: 1, createId: idFactory() });
  const first = store.replaceRetained(undefined, input("first"));
  assert.equal(first.ok, true);
  if (!first.ok) return;
  const oldSnapshot = first.snapshots[0];
  const second = store.replaceRetained(oldSnapshot.id, input("second"));
  assert.equal(second.ok, true);
  if (!second.ok) return;
  assert.equal(store.get(oldSnapshot.id), undefined);
  assert.equal(store.get(second.snapshots[0].id)?.text, "second");
  assert.equal(oldSnapshot.text, "first");
})

test("fails closed after repeated invalid or colliding ids", () => {
  const invalid = new SnapshotStore({ createId: () => "source text" });
  assert.deepEqual(invalid.createMany([input("x")]), { ok: false, reason: "id-collision" });

  const colliding = new SnapshotStore({ createId: () => "snapshot-fixed" });
  assert.equal(colliding.createMany([input("a")]).ok, true);
  assert.deepEqual(colliding.createMany([input("b")]), { ok: false, reason: "id-collision" });
})

test("round-trips content-independent snapshot ids", () => {
  const id = "snapshot-0001";
  const path = virtualPathForSnapshot(id);
  assert.equal(path, "/snapshot/snapshot-0001");
  assert.equal(snapshotIdFromVirtualPath(path), id);
})

test("rejects paths that could carry labels or source text", () => {
  for (const path of [
    "/snapshot/short",
    "/snapshot/id-with/slash",
    "/snapshot/secret%20token",
    "/other/snapshot-0001",
  ]) {
    assert.equal(snapshotIdFromVirtualPath(path), undefined);
  }
  assert.throws(() => virtualPathForSnapshot("secret text"));
})

